// Block (composition) — Panel: a monthly price without and with the gifts spread over it, then what
// the whole contract costs, on ONE sunken panel. Card owns the panel; this Block arranges the amount
// pair, the arrow between them and the totals, and inks its own text (block-contract.md § 5).
//
// Why not PriceSummary: its closing line is a `<p>` note, so a sub-table cannot go inside its panel,
// and the comparison box is one surface holding the pair AND the totals. The pair's markup mirrors
// PriceSummary's (two term-description pairs with the arrow between them, outside both).
//
// Ink: the figure the box competes on takes `text.brand`, the brand figure of the product's colour
// roles (a recurring fee or a benefit), as PlanCardCompact does. PriceSummary inks its discounted
// amount `text.emphasis` (row 10, a sale price); the gift-spread price is not a sale, it is the
// figure the list competes on. The price without gifts stays neutral: the default ink of a value.
import type { Ref } from "react";
import { ArrowRight } from "../components/icons";
import { Card, CardContent } from "../components/Card";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import "./PriceComparison.css";

export interface PriceComparisonAmount {
  /** What the amount is, e.g. "Monthly bill". */
  label: string;
  /** The formatted amount, e.g. "32,780 won a month". */
  amount: string;
}

export interface PriceComparisonTotalRow extends PriceComparisonAmount {
  /** The row the totals add up to (what the customer really pays), drawn bold in the brand ink. */
  isResult?: boolean;
}

export interface PriceComparisonProps {
  /** The monthly price without the gifts, in the neutral ink. Alone (no `after`, an offer with no
   *  gifts), it is the price on offer and takes the brand ink itself. */
  before: PriceComparisonAmount;
  /** The monthly price with the gifts spread over the contract, in the brand ink. */
  after?: PriceComparisonAmount;
  /** What the whole contract costs: a label such as "36-month total" over rows such as total paid,
   *  gifts and net cost, the last marked `isResult`. */
  total?: { label: string; rows: PriceComparisonTotalRow[] };
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function PriceComparison({ before, after, total, className, ref }: PriceComparisonProps) {
  return (
    <Card ref={ref} variant="sunken" className={className ? `sd-pricecomparison ${className}` : "sd-pricecomparison"}>
      <CardContent>
        <Stack gap="medium">
          {/* A `dl` holds only `dt`, `dd` and `div`, so the arrow sits between the two pairs. */}
          <Stack direction="row" align="end" gap="medium" wrap className="sd-pricecomparison__amounts">
            <dl className="sd-pricecomparison__amount">
              <dt className="sd-pricecomparison__label sd-type-label-medium">{before.label}</dt>
              <dd data-emphasized={after ? undefined : true} className="sd-pricecomparison__value sd-type-title-medium-emphasized">
                {before.amount}
              </dd>
            </dl>
            {after && (
              <>
                <ArrowRight aria-hidden size="1.25em" className="sd-pricecomparison__arrow" />
                <dl className="sd-pricecomparison__amount">
                  <dt className="sd-pricecomparison__label sd-type-label-medium">{after.label}</dt>
                  <dd data-emphasized className="sd-pricecomparison__value sd-type-title-medium-emphasized">{after.amount}</dd>
                </dl>
              </>
            )}
          </Stack>
          {total && total.rows.length > 0 && (
            <>
              <Separator isDecorative />
              {/* spacing: attachment — the label heads the rows under it */}
              <Stack gap="x-small">
                <p className="sd-pricecomparison__total-label sd-type-label-medium-emphasized">{total.label}</p>
                <Stack as="dl" gap="2x-small" className="sd-pricecomparison__rows">
                  {total.rows.map((row) => (
                    <Stack key={row.label} direction="row" justify="between" align="baseline" gap="small">
                      <dt
                        data-result={row.isResult || undefined}
                        className={row.isResult ? "sd-pricecomparison__row-label sd-type-body-medium-emphasized" : "sd-pricecomparison__row-label sd-type-body-medium"}
                      >
                        {row.label}
                      </dt>
                      <dd
                        data-result={row.isResult || undefined}
                        className={row.isResult ? "sd-pricecomparison__row-value sd-type-body-medium-emphasized" : "sd-pricecomparison__row-value sd-type-body-medium"}
                      >
                        {row.amount}
                      </dd>
                    </Stack>
                  ))}
                </Stack>
              </Stack>
            </>
          )}
        </Stack>
      </CardContent>
    </Card>
  );
}

/* PriceComparison.css — .sd-pricecomparison (Block)
   Arrangement, plus the ink of this Block's own text (block-contract.md § 5). Card owns the panel.
   The amount names and the totals' row names are keys beside their values (muted); the figure the
   box competes on, and the row the totals add up to, are the brand figure. */
.sd-pricecomparison__label,
.sd-pricecomparison__value,
.sd-pricecomparison__total-label,
.sd-pricecomparison__rows,
.sd-pricecomparison__row-label,
.sd-pricecomparison__row-value {
  margin: 0;
}

.sd-pricecomparison__amount {
  margin: 0;
  display: flex;
  flex-direction: column;
}

.sd-pricecomparison__label,
.sd-pricecomparison__row-label:not([data-result]) {
  color: var(--sd-color-text-muted);
}

.sd-pricecomparison__value[data-emphasized],
.sd-pricecomparison__row-value[data-result] {
  color: var(--sd-color-text-brand);
}

/* The arrow parts two peers, so it takes the muted ink and sits on the amounts' baseline row. */
.sd-pricecomparison__arrow {
  flex: none;
  color: var(--sd-color-text-muted);
  margin-block-end: var(--sd-space-2x-small);
}

.sd-pricecomparison__row-value {
  text-align: end;
}
